RgFloat3D RTGL_V3( float x, float y, float z ) {
    RgFloat3D v = { x, y, z }; return v;
}
RgExtent2D RTGL_Ext( uint32_t w, uint32_t h ) {
    RgExtent2D e = { w, h }; return e;
}

RgNormalPacked32 RTGL_PackNormal( float x, float y, float z ) {
    if ( rg.rgUtilPackNormal ) { return rg.rgUtilPackNormal( x, y, z ); }
    return 0;
}
RgColor4DPacked32 RTGL_PackColorF( float r, float g, float b, float a ) {
    if ( rg.rgUtilPackColorFloat4D ) { return rg.rgUtilPackColorFloat4D( r, g, b, a ); }
    return 0xFFFFFFFFu;
}
RgColor4DPacked32 RTGL_PackColorB( uint8_t r, uint8_t g, uint8_t b, uint8_t a ) {
    if ( rg.rgUtilPackColorByte4D ) { return rg.rgUtilPackColorByte4D( r, g, b, a ); }
    return 0xFFFFFFFFu;
}
RgColor4DPacked32 RTGL_White( void ) { return RTGL_PackColorF( 1.0f, 1.0f, 1.0f, 1.0f ); }

void RTGL_IdentityTransform( RgTransform *t ) {
    memset( t->matrix, 0, sizeof( t->matrix ) );
    t->matrix[0][0] = 1.0f;
    t->matrix[1][1] = 1.0f;
    t->matrix[2][2] = 1.0f;
}

// Doom modelMatrix[16] is column-major (column c = m[c*4+r], translation at
// m[12..14]). RTGL1 wants row-major 3x4. No metric scaling here (raw units).
void RTGL_ModelMatrixToTransform( const float m[16], RgTransform *t ) {
    for ( int row = 0; row < 3; row++ ) {
        for ( int col = 0; col < 3; col++ ) {
            t->matrix[row][col] = m[ col * 4 + row ];
        }
        t->matrix[row][3] = m[ 12 + row ];
    }
}

// P5: RTGL1 emits some warnings/errors EVERY frame (e.g. the known P2 camera
// fallback "No camera provided..." / "Null RgCameraInfo::right", and a
// duplicate directional light). With win_viewlog 1 / pfnPrint these flood the
// log. Throttle by message text: print the first occurrence immediately (so a
// genuine error is never hidden), then only once every rt_dbg_printRepeat
// occurrences, adding a "(repeated N times)" summary. 0 disables throttling.
// Fixed-size table, plain C strings, no STL containers (C++98 friendly).
#define RTGL_MSG_TABLE_MAX 32
#define RTGL_MSG_TEXT_MAX  512
struct RTGLMsgEntry {
    char     text[ RTGL_MSG_TEXT_MAX ];
    int      suppressed;   // occurrences since last print
    int      total;        // total occurrences seen
};
static RTGLMsgEntry s_rtglMsgs[ RTGL_MSG_TABLE_MAX ];
static int          s_rtglMsgCount = 0;

static void RTGL_Print( const char *msg, RgMessageSeverityFlags flags, void * ) {
    const char *text = msg ? msg : "";
    int repeat = rt_dbg_printRepeat.GetInteger();

    if ( repeat > 0 ) {
        // find existing entry (exact text match)
        RTGLMsgEntry *e = NULL;
        for ( int i = 0; i < s_rtglMsgCount; i++ ) {
            if ( strcmp( s_rtglMsgs[ i ].text, text ) == 0 ) { e = &s_rtglMsgs[ i ]; break; }
        }
        if ( !e ) {
            // table full -> never throttle these, just print (fail-safe)
            if ( s_rtglMsgCount >= RTGL_MSG_TABLE_MAX ) { e = NULL; }
            else {
                e = &s_rtglMsgs[ s_rtglMsgCount++ ];
                {
                    int k = 0;
                    for ( ; k < RTGL_MSG_TEXT_MAX - 1 && text[ k ]; k++ ) { e->text[ k ] = text[ k ]; }
                    e->text[ k ] = '\0';
                }
                e->suppressed = 0;
                e->total = 0;
            }
        }
        if ( e ) {
            e->total++;
            // print first occurrence, else only every 'repeat' occurrences
            bool printNow = ( e->total == 1 ) || ( e->suppressed >= repeat );
            if ( !printNow ) { e->suppressed++; return; }
            e->suppressed = 0;
            // append a summary of how many times this message has repeated
            if ( e->total > 1 ) {
                char buf[ RTGL_MSG_TEXT_MAX + 64 ];
                idStr::snPrintf( buf, RTGL_MSG_TEXT_MAX + 64, "%s (repeated %d times)", text, e->total - 1 );
                if ( flags & ( RG_MESSAGE_SEVERITY_ERROR | RG_MESSAGE_SEVERITY_WARNING ) ) {
                    common->Warning( "[RTGL] %s", buf );
                } else {
                    common->Printf( "[RTGL] %s", buf );
                }
                return;
            }
        }
    }

    if ( flags & ( RG_MESSAGE_SEVERITY_ERROR | RG_MESSAGE_SEVERITY_WARNING ) ) {
        common->Warning( "[RTGL] %s", text );
    } else {
        common->Printf( "[RTGL] %s", text );
    }
}

const char * RTGL_ResultString( RgResult r ) {
    switch ( r ) {
        case RG_RESULT_SUCCESS: return "SUCCESS";
        case RG_RESULT_CANT_FIND_DYNAMIC_LIBRARY: return "CANT_FIND_DYNAMIC_LIBRARY";
        case RG_RESULT_CANT_FIND_ENTRY_FUNCTION_IN_DYNAMIC_LIBRARY: return "CANT_FIND_ENTRY_FUNCTION";
        case RG_RESULT_WRONG_FUNCTION_ARGUMENT: return "WRONG_FUNCTION_ARGUMENT";
        case RG_RESULT_WRONG_STRUCTURE_TYPE: return "WRONG_STRUCTURE_TYPE";
        case RG_RESULT_GRAPHICS_API_ERROR: return "GRAPHICS_API_ERROR";
        case RG_RESULT_CANT_FIND_SUPPORTED_PHYSICAL_DEVICE: return "NO_PHYSICAL_DEVICE";
        case RG_RESULT_ERROR_CANT_FIND_SHADER: return "CANT_FIND_SHADER";
        case RG_RESULT_ERROR_CANT_FIND_HARDCODED_RESOURCES: return "CANT_FIND_HARDCODED_RESOURCES";
        default: return "OTHER";
    }
}

bool RTGL_IsActive( void ) { return rgActive; }
bool RTGL_FrameActive( void ) { return rgActive && rgFrameStarted; }

// ---------------------------------------------------------------------------
// lifecycle
// ---------------------------------------------------------------------------
bool RTGL_Init( void ) {
    if ( rgActive ) return true;
    if ( !r_rtgl_enable.GetBool() ) return false;

    static char overridePath[ MAX_PATH ];
    idStr::snPrintf( overridePath, MAX_PATH, "%s", r_rtgl_overridePath.GetString() );

    HWND hwnd = (HWND)GLimp_GetWin32WindowHandle();
    if ( !hwnd ) {
        common->Warning( "RTGL_Init: no Win32 window handle; falling back to OpenGL" );
        return false;
    }

    RgWin32SurfaceCreateInfo win32 = {};
    win32.hinstance = (HINSTANCE)GetModuleHandle( NULL );
    win32.hwnd = hwnd;

    RgInstanceCreateInfo info = {};
    info.sType = RG_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;
    info.version = RG_RTGL_VERSION_API;
    info.sizeOfRgInterface = sizeof( RgInterface );
    info.pAppName = "dhewm3";
    info.pAppGUID = RTGL_APP_GUID;
    info.pWin32SurfaceInfo = &win32;
    info.pOverrideFolderPath = overridePath;
    info.pfnPrint = RTGL_Print;
    info.allowedMessages = RG_MESSAGE_SEVERITY_VERBOSE | RG_MESSAGE_SEVERITY_INFO |
                           RG_MESSAGE_SEVERITY_WARNING | RG_MESSAGE_SEVERITY_ERROR;
    info.primaryRaysMaxAlbedoLayers = 1;
    info.indirectIlluminationMaxAlbedoLayers = 1;
    info.replacementsMaxVertexCount = 32 * 1024 * 1024;
    info.dynamicMaxVertexCount = 2 * 1024 * 1024;
    info.rayCullBackFacingTriangles = 0;
    info.rasterizedMaxVertexCount = 64 * 1024;
    info.rasterizedMaxIndexCount = 128 * 1024;
    info.rasterizedSkyCubemapSize = 256;
    info.pbrTextureSwizzling = RG_TEXTURE_SWIZZLING_NULL_ROUGHNESS_METALLIC;
    // Doom 3 is Z-up. Geometry (P2) and lights (P4) are submitted in RAW engine
    // units: RTGL1 does NOT scale runtime vertices by worldScale (it is only
    // used by the GLTF import/export path), so scaling lights alone would
    // misalign them with the geometry. worldScale here documents the physical
    // unit (1 unit = 0.0254 m) and is consumed only by import/export + the
    // intensity semantics; rt_light_intensity is the visual tuning knob.
    info.worldUp = RTGL_V3( 0.0f, 0.0f, 1.0f );
    info.worldForward = RTGL_V3( 1.0f, 0.0f, 0.0f );
    info.worldScale = 0.0254f;
    info.importedLightIntensityScaleDirectional = 1.0f;
    info.importedLightIntensityScaleSphere = 1.0f;
    info.importedLightIntensityScaleSpot = 1.0f;

    RgResult r = rgLoadLibraryAndCreate( &info, false, NULL, &rg, &rgDll );
    if ( r != RG_RESULT_SUCCESS ) {
        common->Warning( "RTGL_Init: rgLoadLibraryAndCreate failed (%s); falling back to OpenGL", RTGL_ResultString( r ) );
        rg = kZeroRg;
        rgDll = NULL;
        return false;
    }

    rgActive = true;
    g_rtglFrameIndex = 0;
    common->Printf( "RTGL1 initialized (Vulkan path tracing; DXGI present by default; P2 geometry + P3 materials + P4 lights/sky)\n" );
    return true;
}

void RTGL_Shutdown( void ) {
    if ( !rgActive ) return;
    RTGL_HeatHaze_Shutdown();  // app-side heat-haze Vulkan resources (before DLL teardown)
    RTGL_MaterialShutdown();
    RTGL_SkyShutdown();
    if ( rg.rgDestroyInstance ) rg.rgDestroyInstance();
    if ( rgDll ) FreeLibrary( rgDll );
    rg = kZeroRg;
    rgDll = NULL;
    rgActive = false;
    rgFrameStarted = false;
}

// ---------------------------------------------------------------------------
// per-frame
// ---------------------------------------------------------------------------
void RTGL_SubmitFrameCommands( const void *commandChainHead ) {
    if ( !rgActive || !rgFrameStarted ) return;
    RTGL_SubmitCommands( commandChainHead );   // P2/P3: camera + geometry + textures
    RTGL_SubmitSkyGeometry();                  // P4 Path A: 6-face rasterized skybox cube
    RTGL_SubmitLights( commandChainHead );     // P4: viewLights -> RgLight
    RTGL_SubmitUI( commandChainHead );         // P-UI: 2D GUI/console/HUD swapchain overlays
    RTGL_SubmitWorldGuis( commandChainHead );  // P-UI: in-world interactive GUI surfaces (3D-view SS_GUI quads)
    RTGL_ReportStats();                        // after all, so all counters are final
}

void RTGL_BeginFrame( int windowWidth, int windowHeight ) {
    if ( !rgActive || !rg.rgStartFrame ) return;

    g_rtglWidth = windowWidth;
    g_rtglHeight = windowHeight;
    g_rtglFrameIndex++;
    g_rtglCameraUploaded = false;
    g_rtglStats.Clear( g_rtglFrameIndex );
    RTGL_SubmitBeginFrame();
    RTGL_MaterialBeginFrame();
    RTGL_LightBeginFrame();
    RTGL_SkyBeginFrame();

    RgStartFrameRenderResolutionParams res = {};
    res.sType = RG_STRUCTURE_TYPE_START_FRAME_RENDER_RESOLUTION_PARAMS;
    res.upscaleTechnique = RG_RENDER_UPSCALE_TECHNIQUE_LINEAR;
    res.resolutionMode = RG_RENDER_RESOLUTION_MODE_NATIVE_AA;
    res.frameGeneration = RG_FRAME_GENERATION_MODE_OFF;
    // Present via the DXGI/DX12 swapchain (default for the RTGL backend,
    // (same mechanism as gzdoom-rt's rt_dxgi=1). If D3D12/DXGI is unavailable,
    // RTGL1 sanitizes this back to a native Vulkan swapchain internally
    // (Swapchain.cpp), so no cvar / conditional branch is needed here.
    res.preferDxgiPresent = true;
    res.sharpenTechnique = RG_RENDER_SHARPEN_TECHNIQUE_NONE;
    res.customRenderSize = RTGL_Ext( (uint32_t)windowWidth, (uint32_t)windowHeight );
    res.pixelizedRenderSize = res.customRenderSize;

    RgStartFrameInfo si = {};
    si.sType = RG_STRUCTURE_TYPE_START_FRAME_INFO;
    si.pNext = &res;
    si.pMapName = "dhewm3";
    si.vsync = false;
    si.hdr = false;

    RgResult r = rg.rgStartFrame( &si );
    rgFrameStarted = ( r == RG_RESULT_SUCCESS );
    if ( !rgFrameStarted ) common->Warning( "RTGL_BeginFrame: rgStartFrame failed (%s)", RTGL_ResultString( r ) );
}

// Fallback camera: used only if no RC_DRAW_VIEW supplied one this frame.
static void RTGL_DefaultCamera( void ) {
    if ( g_rtglCameraUploaded || !rg.rgUploadCamera ) return;
    RgCameraInfo cam = {};
    cam.sType = RG_STRUCTURE_TYPE_CAMERA_INFO;
    cam.pNext = NULL;
    cam.flags = 0;
    cam.position = RTGL_V3( 0.0f, 0.0f, 0.0f );
    cam.up    = RTGL_V3( 0.0f, 0.0f, 1.0f );
    cam.right = RTGL_V3( 0.0f, 1.0f, 0.0f );
    cam.fovYRadians = 1.0471976f;
    float w = ( g_rtglWidth  > 0 ) ? (float)g_rtglWidth  : 640.0f;
    float h = ( g_rtglHeight > 0 ) ? (float)g_rtglHeight : 480.0f;
    cam.aspect = w / h;
    cam.cameraNear = 0.1f;
    cam.cameraFar = 10000.0f;
    cam.pView = NULL;
    RgResult r = rg.rgUploadCamera( &cam );
    if ( r != RG_RESULT_SUCCESS ) common->Warning( "RTGL_EndFrame: rgUploadCamera failed (%s)", RTGL_ResultString( r ) );
}

void RTGL_EndFrame( void ) {
    if ( !rgActive || !rgFrameStarted ) return;

    RTGL_DefaultCamera();  // present a valid camera even for an empty frame

    // P4: build tonemapping + textures + illumination + sky params and link
    // them into the pNext chain.
    // Critically:
    // 1) RTGL1's default `taaAntiSparkle = 0.25f` clamps every new frame's
    //    `unfilteredDirect` to `1.414 * neighbourMean` in `CmSVGFTemporalAccumulation.comp`,
    //    which crushes 1-spp ReSTIR DI samples (where half the 3x3 neighbours
    //    chose a different light and are 0) and makes filtered `diffuse direct`
    //    much darker than `unfiltered diffuse direct`. Setting `taaAntiSparkle = 0.0f`
    //    and `taaVarianceGamma = 6.0f` preserves full direct diffuse energy.
    // 2) Setting `ev100Min = -2.0f` (instead of default `0.0f`) lets auto-exposure
    //    properly expose dark Doom 3 rooms without crushing midtones.
    // 3) Setting `emissionMapBoost = 2.0f` (instead of default `100.0f`) allows
    //    `rt_emissive_enable = 1` (`rt_emissive_mult = 0.35`) to make fixture
    //    panels visibly glow on screen without flooding indirect GI.
    RgDrawFrameTonemappingParams tnmp = {};
    tnmp.sType = RG_STRUCTURE_TYPE_DRAW_FRAME_TONEMAPPING_PARAMS;
    tnmp.pNext = NULL;
    tnmp.disableEyeAdaptation = 0;
    tnmp.ev100Min = -2.0f;
    tnmp.ev100Max = 7.0f;
    tnmp.luminanceWhitePoint = 10.0f;
    tnmp.saturation = RTGL_V3( 0.0f, 0.0f, 0.0f );
    tnmp.crosstalk = RTGL_V3( 1.0f, 1.0f, 1.0f );
    tnmp.contrast = 0.05f;
    tnmp.hdrBrightness = 1.0f;
    tnmp.hdrContrast = 0.1f;
    tnmp.hdrSaturation = RTGL_V3( 0.25f, 0.25f, 0.25f );

    RgDrawFrameTexturesParams texParams = {};
    texParams.sType = RG_STRUCTURE_TYPE_DRAW_FRAME_TEXTURES_PARAMS;
    texParams.pNext = &tnmp;
    texParams.dynamicSamplerFilter = RG_SAMPLER_FILTER_LINEAR;
    texParams.normalMapStrength = 1.0f;
    texParams.emissionMapBoost = rt_emissive_enable.GetBool() ? 2.0f : 0.0f;
    texParams.emissionMaxScreenColor = rt_emissive_enable.GetBool() ? 1.5f : 0.0f;
    texParams.minRoughness = 0.0f;
    texParams.heightMapDepth = 0.02f;
    texParams.clampDirect = 500.0f;
    texParams.clampIndirect = 500.0f;
    texParams.clampSpecular = 500.0f;
    texParams.indirectMaxSolidAngle = 0.05f;
    texParams.taaVarianceGamma = 6.0f;
    texParams.taaAntiSparkle = 0.0f;

    RgDrawFrameIlluminationParams illum;
    RTGL_BuildIlluminationParams( &illum );
    illum.pNext = &texParams;

    RgDrawFrameReflectRefractParams refr = {};
    refr.sType = RG_STRUCTURE_TYPE_DRAW_FRAME_REFLECT_REFRACT_PARAMS;
    refr.pNext = &illum;
    refr.maxReflectRefractDepth = rt_refr_enable.GetBool() ? (uint32_t)rt_refr_depth.GetInteger() : 0;
    refr.typeOfMediaAroundCamera = RG_MEDIA_TYPE_VACUUM;
    refr.indexOfRefractionGlass = 1.52f;
    refr.indexOfRefractionWater = rt_refr_index.GetFloat();
    refr.thinMediaWidth = 0.0f;
    refr.waterWaveSpeed = rt_refr_waveSpeed.GetFloat();
    refr.waterWaveNormalStrength = rt_refr_waveStrength.GetFloat();
    refr.waterColor = RTGL_V3( 1.0f, 1.0f, 1.0f );
    refr.acidColor = RTGL_V3( 1.0f, 1.0f, 1.0f );
    refr.acidDensity = 0.0f;
    refr.waterWaveTextureDerivativesMultiplier = 1.0f;
    refr.waterTextureAreaScale = 1.0f;
    refr.portalNormalTwirl = 0;

    // The app draws the heat-haze pass itself (rtgl_heathaze.cpp). RTGL1 only
    // provides the injection point (RgDrawFrameCustomPassParams callback);
    // the DLL no longer renders anything. pUserData stays NULL (unused).
    RgDrawFrameCustomPassParams customPass = {};
    customPass.sType = RG_STRUCTURE_TYPE_DRAW_FRAME_CUSTOM_PASS_PARAMS;
    customPass.pNext = &refr;
    customPass.pfnCallback = RTGL_HeatHaze_CustomPass;
    // Stage-2 A/B: rt_raster_distortion=1 -> app draws (pass NULL so the
    // DLL CustomPass::Render early-returns, no double draw); =0 -> DLL draws.
    customPass.pUserData = NULL;

    RgDrawFrameSkyParams sky;
    RTGL_BuildSkyParams( &sky );
    // DIAG: override the sky with a bright, unmistakable COLOR so any pixel
    // that is actually the ray-miss background (storeSky) can be identified.
    // Normally an indoor scene sets skyColorDefault=(0,0,0) and multiplier=0,
    // and a raster-sky scene samples a cubemap ignoring skyColorDefault, so
    // both paths must be forced here for the test to be conclusive.
    if ( rt_dbg_forceSkyColor.GetBool() ) {
        sky.skyType = RG_SKY_TYPE_COLOR;
        sky.skyColorDefault = RTGL_V3( 1.0f, 0.0f, 1.0f );
        sky.skyColorMultiplier = 1.0f;
        sky.skyColorSaturation = 1.0f;
        sky.skyColorScale = 1.0f;
        sky.skyLightMultiplier = 0.0f;
        sky.skyLightScale = 0.0f;
    }
    sky.pNext = &customPass;

    RgDrawFrameInfo di = {};
    di.sType = RG_STRUCTURE_TYPE_DRAW_FRAME_INFO;
    di.pNext = &sky;
    di.rayLength = 10000.0f;
    di.currentTime = rgTime;
    // DIAG switches: isolate which RTGL1 internal channel still produces the
    // grey quad now that ALL sort>=100 surfaces are intercepted CPU-side.
    di.disableRasterization     = rt_dbg_disableRaster.GetBool() ? 1 : 0;
    di.resetHistory             = rt_dbg_resetHistory.GetBool() ? 1 : 0;
    di.disableRayTracedGeometry = rt_dbg_disableRTGeom.GetBool() ? 1 : 0;
    rgTime += 1.0 / 60.0;

    RgResult r = rg.rgDrawFrame( &di );
    if ( r != RG_RESULT_SUCCESS ) common->Warning( "RTGL_EndFrame: rgDrawFrame failed (%s)", RTGL_ResultString( r ) );
    rgFrameStarted = false;
}

#endif // D3_RTGL
